// Pure: a re-attached file (F03-R3). The first line of a `file` attachment's text holds the Read call's input as JSON.
import type { External } from '../model/external'
import type { Reattached } from '../model/reattached'
import { estimateTokens } from './measure'
import { normalize } from './path'

export function reattachedAction(text: string, cwd: string): Reattached | null {
  const json = /^Called the Read tool with the following input: (\{.*\})$/.exec(text.split('\n', 1)[0]!)?.[1]
  let input: unknown
  try { input = json && JSON.parse(json) } catch { return null }
  const file = typeof input === 'object' && input !== null && 'file_path' in input ? input.file_path : null
  return typeof file === 'string'
    ? { type: 'reattached', path: normalize(file, cwd), tokens: estimateTokens(text) } : null
}

/** F07-R7: the file an `edited_text_file` attachment names, from its "Note: ‹path› changed on disk since you last read it" line (F07-Q1, recorded); null when the text has none (the reducer then matches it against known nodes). */
export function externalAction(text: string, cwd: string): External {
  const path = /^Note: (.+?) (?:changed on disk|was modified)\b/m.exec(text)?.[1]
  return { type: 'external', path: path ? normalize(path, cwd) : null, text }
}

files.hooks/parse/grep.ts:
// Pure: F07-R2, R3. The `git grep` that finds the files importing a changed one, and the confirmation of its hits.
import { candidatesFor, importsIn } from './imports'
import { normalize, worktreeOf } from './path'

export const PATHSPECS = ['*.ts', '*.tsx', '*.mts', '*.cts', '*.js', '*.jsx', '*.mjs', '*.cjs', '*.py']

const escape = (s: string) => s.replace(/[.^$*+?()[\]{}|\\]/g, '\\$&')

/**
 * An extended regular expression for the lines that import a file named like `path` without its extension (a changed `index` or `__init__` is named by its folder): a JavaScript or TypeScript import line (F06-R2) whose quoted specifier ends in `/name`, or a Python `from`/`import` line that holds the name.
 * Deliberately loose: `importersOf` confirms each hit. ponytail: one line at a time, so the names on the earlier lines of a multi-line import are not read.
 */
export function importPattern(path: string): string {
  const [, folder, base = ''] = /(?:([^/]+)\/)?([^/]+?)(?:\.[^./]+)?$/.exec(path)!
  const index = folder !== undefined && (base === 'index' || base === '__init__')
  const name = escape(index ? folder! : base)
  return `(import|export|require|from)[^'"]*['"][^'"]*/${name}${index ? `(/${base})?` : ''}(\\.[A-Za-z]+)?['"]|^[[:space:]]*(from|import)([[:space:]].*)?[^[:alnum:]_]${name}([^[:alnum:]_]|$)`
}

/** The hits of `git grep -n`: `file:line:text`. */
export const grepHits = (stdout: string) =>
  stdout.split('\n').flatMap(l => {
    const m = /^(.+?):\d+:(.*)$/.exec(l)
    return m ? [{ file: m[1]!, text: m[2]! }] : []
  })

/**
 * F07-R3: the node paths (I4) of the hits whose import resolves to `changed`. `git grep` runs in `root`, so its paths are relative to it.
 * A file of an agent's worktree is skipped (F07-R15).
 */
export function importersOf(stdout: string, changed: string, root: string, cwd: string): string[] {
  const out: string[] = []
  for (const { file, text } of grepHits(stdout)) {
    const abs = `${root}/${file}`
    const path = normalize(abs, cwd)
    if (worktreeOf(abs, cwd) || path === changed || out.includes(path)) continue
    if (importsIn(/^\s*}/.test(text) ? `import ${text}` : text, path).some(s => candidatesFor(s, path, cwd).includes(changed))) out.push(path)
  }
  return out
}

files.hooks/parse/fileRead.ts:
// Pure: a Read's result becomes a `fileRead` action, or null for a kind not tracked.
import type { FileRead, FileUnchanged } from '../model/fileRead'
import { importCandidates } from './imports'
import { estimateTokens, plural } from './measure'

type TextFile = { content: string; numLines: number; startLine: number; totalLines: number; truncatedByTokenCap?: boolean }
type ReadResult = { type: 'text'; file: TextFile } | { type: string }

function text(path: string, readId: string, f: TextFile, cwd: string, importEdges: boolean): FileRead {
  const isWhole = f.startLine === 1 && f.numLines >= f.totalLines && !f.truncatedByTokenCap
  return {
    type: 'fileRead', path, readId, state: isWhole ? 'read' : 'partial', tokens: estimateTokens(f.content),
    seen: isWhole ? plural(f.numLines, 'line') : `lines ${f.startLine} to ${f.startLine + f.numLines - 1} of ${f.totalLines}`,
    imports: importEdges ? importCandidates(f.content, path, cwd) : undefined,
  }
}

// F01-R2: what the pane cannot estimate shows as `read` with no tokens and a `seen` that names the kind.
const opaque = (path: string, readId: string, seen: string): FileRead =>
  ({ type: 'fileRead', path, readId, state: 'read', tokens: null, seen })

export function readAction(path: string, readId: string, result: ReadResult, cwd: string, importEdges: boolean): FileRead | FileUnchanged | null {
  switch (result.type) {
    case 'text': return text(path, readId, (result as { file: TextFile }).file, cwd, importEdges)
    case 'file_unchanged': return { type: 'fileUnchanged', path }
    case 'image': return opaque(path, readId, 'image')
    case 'pdf': return opaque(path, readId, 'PDF')
    case 'parts': {
      const { firstPage = 1, file } = result as { firstPage?: number; file?: { count?: number } }
      return opaque(path, readId, `PDF pages ${firstPage} to ${firstPage + (file?.count ?? 1) - 1}`)
    }
    case 'notebook': {
      const n = (result as { file?: { cells?: unknown[] } }).file?.cells?.length ?? 0
      return opaque(path, readId, `notebook, ${plural(n, 'cell')}`)
    }
    default: return null
  }
}

files.hooks/parse/fileWritten.ts:
// Pure: a Write's result becomes a `fileWritten` action, or null when staged.
import type { FileWritten } from '../model/fileWritten'
import { importCandidates } from './imports'
import { count, countLines, estimateTokens, type Hunk } from './measure'

type WriteResult = { type: 'create' | 'update'; content: string; structuredPatch: Hunk[]; staged?: boolean }

export function writeAction(path: string, r: WriteResult, cwd: string, importEdges: boolean): FileWritten | null {
  if (r.staged) return null
  const created = r.type === 'create'
  // F01-R6: an empty patch counts the content's lines for a create only.
  const whole = created && r.structuredPatch.length === 0
  return {
    type: 'fileWritten', path, created, tokens: estimateTokens(r.content),
    added: whole ? countLines(r.content) : count(r.structuredPatch, '+'),
    removed: count(r.structuredPatch, '-'), line: r.structuredPatch[0]?.newStart ?? 1,
    imports: importEdges ? importCandidates(r.content, path, cwd) : undefined,
  }
}

files.hooks/parse/mention.ts:
// Pure: a `prompt.mention` result becomes a `mention` action, or null when nothing was attached.
import type { Mention } from '../model/mention'

export function mentionAction(path: string, e: { offset?: number; limit?: number }, type: string | null): Mention | null {
  if (type === 'pdf_reference') return { type: 'mention', path, state: 'ghost', seen: 'mentioned PDF, not attached' }
  if (type !== 'file' && type !== 'already_read_file') return null
  if (e.offset === undefined && e.limit === undefined) return { type: 'mention', path, state: 'read', seen: 'mentioned by you' }
  const from = e.offset ?? 1
  const range = e.limit === undefined ? `from line ${from}` : `lines ${from} to ${from + e.limit - 1}`
  return { type: 'mention', path, state: 'partial', seen: `${range}, mentioned by you` }
}

