// Pure: a `classic.InstructionsLoaded` input becomes a memory note (F04-R3).
import type { MemoryNote } from '../../types'
import { estimateTokens } from './measure'
import { normalize } from './path'

const REASON = { session_start: 'at start', nested_traversal: 'nested', path_glob_match: 'path rule', include: 'import', compact: 'after compaction' } as const

export const memoryNote = (e: { file_path: string; memory_type: string; load_reason: keyof typeof REASON }, cwd: string): MemoryNote =>
  ({ path: normalize(e.file_path, cwd), type: e.memory_type, tokens: null, reason: REASON[e.load_reason] })

/** F04-R1: the memory files a usage breakdown lists, as notes without a reason. */
export const listed = (files: Omit<MemoryNote, 'reason'>[], cwd: string): MemoryNote[] =>
  files.map(f => ({ path: normalize(f.path, cwd), type: f.type, tokens: f.tokens, reason: null }))

/** F04-R6: the path in the first line of a nested file's attachment ("Contents of <path>:"), and the estimate of the whole text. */
export const nestedSize = (text: string, cwd: string) => {
  const path = /^Contents of (.+):\n/.exec(text)?.[1]
  return path ? { path: normalize(path, cwd), tokens: estimateTokens(text) } : null
}

files.hooks/parse/path.ts:
// Pure: I4. Lexical normalization; relative to `cwd` when inside it, absolute otherwise.
const clean = (p: string): string => {
  p = p.replace(/\\/g, '/')
  const drive = /^[a-z]:/i.exec(p)?.[0].toLowerCase() ?? ''
  const rest = p.slice(drive.length)
  const out: string[] = []
  for (const s of rest.split('/')) s === '..' ? out.pop() : s !== '' && s !== '.' && out.push(s)
  return drive + (rest.startsWith('/') ? '/' : '') + out.join('/')
}

// F15-R9: `.claude/worktrees/<name>/<file>` inside the cwd. ponytail: a worktree a WorktreeCreate hook puts elsewhere stays an absolute path.
const WORKTREE = /^\.claude\/worktrees\/([^/]+)\/(.+)$/

const split = (path: string, cwd: string) => {
  const p = clean(path)
  const c = clean(cwd)
  const base = c.endsWith('/') ? c : c + '/'
  const rel = c !== '' && p.startsWith(base) ? p.slice(base.length) : null
  const wt = rel === null ? null : WORKTREE.exec(rel)
  return { path: wt ? wt[2]! : rel ?? p, worktree: wt ? wt[1]! : null }
}

export const normalize = (path: string, cwd: string): string => split(path, cwd).path
export const worktreeOf = (path: string, cwd: string): string | null => split(path, cwd).worktree
export const isAbs = (p: string) => /^([a-z]:)?[\\/]/i.test(p)

