// Pure: what a shell command did to files, from git's status around it (F07-R6).
import type { FileNode, Graph } from '../../types'
import type { ShellChange } from '../parse/status'
import { cut } from '../parse/shell'
import { touch } from './node'

/** `agentId`: the subagent whose command it was (F15-R1). */
export type ShellChanged = { type: 'shellChanged'; command: string; changes: ShellChange[]; worktree?: string; agentId?: string }

/** F07-R17: a change the command named is Claude's own, as an Edit is (F01-R4): a node with nothing of the file in context becomes partial, or takes what Claude had of the file a `mv` moved here (`moved`); a search node keeps its tokens and readId. */
const own = (o: FileNode | undefined, moved?: FileNode): Partial<FileNode> =>
  (!o || o.state === 'ghost' || o.state === 'unread') && moved && moved.state !== 'ghost' && moved.state !== 'unread' ? { state: moved.state, tokens: moved.tokens, seen: moved.seen, readId: moved.readId }
    : !o || o.state === 'ghost' || o.state === 'unread' ? { state: 'partial', tokens: null, readId: null, seen: 'only what the command changed' }
    : o.state === 'search' ? { state: 'partial', seen: 'only what the command changed' }
      : {}

/** F07-R6: a reverted path loses its change, and the blind edges to it, since nothing changed is left to miss. A path with no node, or none to clear, is left alone. */
function reverted(g: Graph, path: string, turn: number, agentId?: string): Graph {
  if (!g.files[path]?.change) return g
  const out = touch(g, path, turn, () => ({ change: null, reason: null, added: 0, removed: 0 }), agentId)
  return out.edges.some(e => e.to === path && e.blind) ? { ...out, edges: out.edges.map(e => (e.to === path ? { ...e, blind: false } : e)) } : out
}

/**
 * F07-R6: each changed path touched once. A deletion always shows; a creation replaces no change but a deletion; any other change (`blind` or `edited`, F07-R17) leaves alone what Claude's own Write or Edit did.
 * A new node, or a ghost, becomes `unread`: Claude has not seen what the command wrote. One the command named is Claude's own (`own`).
 */
export const shellChanged = (g: Graph, a: ShellChanged, turn: number): Graph =>
  a.changes.reduce((g, { path, change, named, from, history, added, removed }) => {
    const old = g.files[path]?.change ?? null
    if (change === 'reverted' || (history && change === 'created' && old === 'deleted')) return reverted(g, path, turn, a.agentId) // F07-R14: brought back from history
    const keep = change === 'created' ? old !== null && old !== 'deleted' : change !== 'deleted' && (old === 'edited' || old === 'created')
    if (keep) return added !== undefined && old === 'created' ? touch(g, path, turn, () => ({ added }), a.agentId) : g // F07-R23: a created file's new length
    return touch(g, path, turn, o => ({
      ...(named ? own(o, from ? g.files[from] : undefined) : !o || o.state === 'ghost' ? { state: 'unread' as const, tokens: null, seen: 'never read' } : {}),
      change,
      ...(added !== undefined && (change === 'created' ? { added } : change === 'edited' && { added, removed })), // F07-R23
      reason: `${change === 'blind' || change === 'edited' ? 'changed' : change} by \`${cut(a.command)}\`${a.worktree ? ` in worktree ${a.worktree}` : ''}`, // F07-R16
    }), a.agentId)
  }, g)

files.hooks/model/node.ts:
// Pure: the one way a reducer touches a node (F01-R9). Every file action goes through here.
import type { FileNode, Graph } from '../../types'

const fresh = (path: string, turn: number): FileNode => ({
  path, state: 'ghost', change: null, reason: null, tokens: null, seen: '', hits: 0, added: 0, removed: 0,
  line: null, readId: null, agents: [], mainLoop: true, firstTurn: turn, lastTurn: turn, touched: 0,
})

// F15-R8: the fields that describe what the main conversation holds.
const owned = ({ state, tokens, seen, readId, hits }: FileNode) => ({ state, tokens, seen, readId, hits })

/**
 * Creates the node when missing, merges `patch(old)` over it, stamps `lastTurn` and `touched`, bumps `seq`.
 * F15-R1: a call from an agent adds its id to `agents` once, and a node it creates is subagent only; a call without one sets `mainLoop`.
 * F15-R8: once `mainLoop` is true an agent's call leaves `owned` alone; the main loop's first touch of a subagent-only node sets them as if the node were new.
 */
export function touch(g: Graph, path: string, turn: number, patch: (old: FileNode | undefined) => Partial<FileNode>, agentId?: string): Graph {
  const old = g.files[path]
  const seq = g.seq + 1
  const agents = old?.agents ?? []
  const who = { agents: agentId && !agents.includes(agentId) ? [...agents, agentId] : agents, mainLoop: agentId ? old?.mainLoop ?? false : true }
  // Whose view of `owned` wins over the patch: the main loop's kept one, a new node's, or the patch's own (none).
  const owner = agentId && old?.mainLoop ? old
    : !agentId && old && !old.mainLoop ? { ...fresh(path, turn), ...patch(undefined) }
    : null
  const node = { ...(old ?? fresh(path, turn)), ...patch(old), ...(owner && owned(owner)), ...who, path, lastTurn: turn, touched: seq }
  // F07-R4: a ghost that is opened, or changed, is no blind spot.
  const edges = old?.state === 'ghost' && node.state !== 'ghost' && g.edges.some(e => e.from === path && e.blind) ? g.edges.map(e => (e.from === path ? { ...e, blind: false } : e)) : g.edges
  return { ...g, seq, edges, files: { ...g.files, [path]: node } }
}

/** F06-R7: a node for a file nobody has opened. Nobody holds it (`mainLoop` false, no agents), and it shares the event's `seq` rather than bumping it. */
export const ghost = (g: Graph, path: string, turn: number): Graph =>
  g.files[path] ? g : { ...g, files: { ...g.files, [path]: { ...fresh(path, turn), mainLoop: false, touched: g.seq } } }

/** F15-R9: a change in a worktree says so, unless this tree already has a change of its own (`change` set, `reason` null). */
export const worktreeReason = (old: FileNode | undefined, worktree?: string): string | null =>
  worktree && !(old?.change && old.reason === null) ? `in worktree ${worktree}` : null

files.hooks/parse/imports.ts:
import type { ImportTarget } from '../model/imports'
import { isAbs, normalize } from './path'

// Pure: F06. The imports of a text Claude's own tool result carried, one entry per language (F06 Implementation decisions).
type Language = {
  extensions: string[]
  /** Every module specifier the text names, in order, bare ones included. */
  specifiers: (text: string) => string[]
  /** Ordered candidate paths for one specifier, as node paths (I4); none for a specifier the language does not link. */
  candidatesFor: (specifier: string, importer: string, workingDir: string) => string[]
  /** True for a specifier that may only link to a node that already exists (F06-R3, R4). */
  existingOnly?: (specifier: string) => boolean
}

const TS_FAMILY = ['.ts', '.tsx', '.mts', '.cts']
const JS_FAMILY = ['.js', '.jsx', '.mjs', '.cjs']
const CODE = [...TS_FAMILY, ...JS_FAMILY]
// `./util.js` in a TypeScript file names `util.ts` or `util.tsx`, as TypeScript resolves it.
const TWINS: Record<string, string[]> = { '.js': ['.ts', '.tsx'], '.jsx': ['.tsx'], '.mjs': ['.mts'], '.cjs': ['.cts'] }
const extOf = (path: string) => /\.[^./]+$/.exec(path)?.[0] ?? ''
const dirOf = (path: string) => path.slice(0, path.lastIndexOf('/') + 1)

/** `rel` against the importer's folder, as a node path (I4): relative inside the working directory, absolute outside. */
const near = (importer: string, rel: string, workingDir: string) =>
  normalize(`${isAbs(importer) ? '' : workingDir + '/'}${dirOf(importer)}${rel}`, workingDir)

// Left to right, so a comment or string that starts earlier swallows what looks like an import inside it.
// ponytail: a regex literal or a `${}` holding a quote can still confuse this; a real tokenizer if a recording shows it.
const TS_TOKENS = new RegExp([
  String.raw`\/\/[^\n]*|\/\*[\s\S]*?\*\/`,
  String.raw`\b(?:import|export)\b[^'"` + '`' + String.raw`;=()]*?\bfrom\s*(['"])(.+?)\1`,
  String.raw`\bimport\s*(['"])(.+?)\3`,
  String.raw`(?<![.\w$])(?:require|import)\s*\(\s*(['"])(.+?)\5\s*\)`,
  String.raw`'(?:\\.|[^'\\\n])*'|"(?:\\.|[^"\\\n])*"|` + '`(?:\\\\.|[^`\\\\])*`',
].join('|'), 'g')

const typescript: Language = {
  extensions: CODE,
  specifiers: text => [...text.matchAll(TS_TOKENS)].flatMap(m => m[2] ?? m[4] ?? m[6] ?? []),
  candidatesFor(spec, importer, workingDir) {
    if (!/^\.\.?(\/|$)/.test(spec)) return [] // F06-R5: packages, `node:`, aliases
    const at = (rel: string) => near(importer, rel, workingDir)
    const ts = TS_FAMILY.includes(extOf(importer))
    const exts = ts ? CODE : [...JS_FAMILY, ...TS_FAMILY]
    const written = extOf(spec)
    if (CODE.includes(written)) return [...(ts ? TWINS[written] ?? [] : []).map(t => at(spec.slice(0, -written.length) + t)), at(spec)]
    const index = exts.map(x => at(`${spec}/index${x}`))
    return /(^|\/)\.\.?\/?$|\/$/.test(spec) ? index : [...exts.map(x => at(spec + x)), ...index] // `.`, `..` and `x/` name a folder
  },
  // `./styles.css` is no module; `./user.service` may be `user.service.ts`. Without the disk, only an existing node tells them apart.
  existingOnly: spec => extOf(spec) !== '' && !CODE.includes(extOf(spec)),
}

// ponytail: a statement after `;` or `:` (`if TYPE_CHECKING: import x`), a line continuation (`\`) or a `)` inside a string in a parenthesised list can still confuse this; a real tokenizer if a recording shows it.
// Left to right like TS_TOKENS; statements start a line. Groups: 1 `from` module, 2|3 its names, 4 `import` list.
const PY_TOKENS = new RegExp([
  String.raw`#[^\n]*`,
  String.raw`"""[\s\S]*?"""|'''[\s\S]*?'''`,
  String.raw`"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'`,
  String.raw`^[ \t]*from[ \t]+(\.*[A-Za-z_][\w.]*|\.+)[ \t]+import[ \t]*(?:\(([^)]*)\)|([^\n#;]*))`,
  String.raw`^[ \t]*import[ \t]+([^\n#;]*)`,
].join('|'), 'gm')

/** The first word of each comma-separated item (`a as b, c` gives `a`, `c`), comments dropped; `*` gives none. */
const pyNames = (list: string) =>
  list.replace(/#[^\n]*/g, '').split(',').flatMap(i => /^\s*([A-Za-z_][\w.]*)/.exec(i)?.[1] ?? [])

const python: Language = {
  extensions: ['.py'],
  specifiers: text => [...text.matchAll(PY_TOKENS)].flatMap(m =>
    m[1] === undefined ? pyNames(m[4] ?? '') : /^\.+$/.test(m[1]) ? pyNames(m[2] ?? m[3] ?? '').map(n => m[1] + n) : [m[1]]), // `from . import x` names the module `.x`
  candidatesFor(spec, importer, workingDir) {
    const dots = /^\.*/.exec(spec)![0].length
    const module = spec.slice(dots).replace(/\./g, '/')
    const base = dots ? near(importer, '../'.repeat(dots - 1) + module, workingDir) : module // absolute: already relative to the working directory
    return [base + '.py', base + '/__init__.py']
  },
  existingOnly: spec => !spec.startsWith('.'),
}

const languages: Language[] = [typescript, python]
const MAX_CHARS = 200_000 // F06-R9

const languageOf = (path: string) => languages.find(l => l.extensions.includes(extOf(path)))

/** F06-R2, R11: the specifiers the text of `path` names, none for a file of no known language. */
export const importsIn = (text: string, path: string): string[] =>
  text.length > MAX_CHARS ? [] : languageOf(path)?.specifiers(text) ?? []

/** F06-R3, R5: ordered candidate paths for one specifier of `importer`. */
export const candidatesFor = (specifier: string, importer: string, workingDir: string): string[] =>
  languageOf(importer)?.candidatesFor(specifier, importer, workingDir) ?? []

/** The candidates of every linkable import in `text`, one per specifier. */
export const importCandidates = (text: string, importer: string, workingDir: string): ImportTarget[] => {
  const lang = languageOf(importer)
  return !lang ? [] : importsIn(text, importer).flatMap(s => {
    const candidates = lang.candidatesFor(s, importer, workingDir)
    return candidates.length ? [{ candidates, ...(lang.existingOnly?.(s) && { existing: true }) }] : []
  })
}

