{
  "name": "cc-graph",
  "version": "0.3.0",
  "description": "A live graph of what Claude Code knows, read and changed",
  "author": {
    "name": "Lars Kühn"
  },
  "homepage": "https://github.com/kuehn-lars/cc-graph",
  "repository": "https://github.com/kuehn-lars/cc-graph",
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "maxNodes": {
      "type": "number",
      "title": "Most files in the graph",
      "description": "The graph keeps at most this many files; the oldest unchanged ones leave first. Files Claude changed always stay.",
      "default": 60,
      "min": 20,
      "max": 200
    },
    "importEdges": {
      "type": "boolean",
      "title": "Show file imports",
      "description": "Link a file to the files it imports. Off, the graph holds only the files Claude touched.",
      "default": true
    },
    "blindSpots": {
      "type": "boolean",
      "title": "Look for blind spots with git",
      "description": "Run read-only git to find files a shell command changed and importers Claude never opened. Off, shell reads still show.",
      "default": true
    }
  }
}
